import {registerHill,hillSurface} from './terrain-height.js';
import * as T from './vendor/three.module.js';
import {landMaterial} from './land-materials.js';
// Authored landmarks, seeded detail. Roads and quest points are reserved, never mirrored.
export function dressRegion({root,zone,x,w,h,wall=()=>{},reserved=[]}){
 const g=new T.Group();g.name='region-dressing-'+zone;root.add(g);const rock=landMaterial('rock',0x93a49a),soil=landMaterial('soil',0x8b9b7d),wood=landMaterial('bark',0x9e9176),leaves=landMaterial('soil',0x365544),path=landMaterial('path',0xaaa18b),metal=landMaterial('rock',0x65736f);
 const add=(geo,mat,xx,y,z)=>{const m=new T.Mesh(geo,mat);m.position.set(x+xx,y,z);g.add(m);return m},box=(xx,y,z,a,b,c,mat=wood)=>add(new T.BoxGeometry(a,b,c),mat,xx,y,z);
 const safe=(xx,z,r)=>Math.abs(xx)<w/2-r-5&&z< -28-r&&z> -h+26+r&&!reserved.some(p=>Math.hypot(x+xx-p.x,z-p.z)<r+7);
 function trail(points,width=5){root.userData.decorRoads??=[];for(let i=0;i<points.length-1;i++){const a=points[i],b=points[i+1],steps=Math.ceil(Math.hypot(a[0]-b[0],a[1]-b[1])/6);for(let j=0;j<=steps;j++)root.userData.decorRoads.push([x+a[0]+(b[0]-a[0])*j/steps-width/2,a[1]+(b[1]-a[1])*j/steps-3,width,6])}const pos=[],uv=[];for(let i=0;i<points.length;i++){const [xx,z]=points[i],a=points[Math.max(0,i-1)],b=points[Math.min(points.length-1,i+1)],dx=b[0]-a[0],dz=b[1]-a[1],len=Math.hypot(dx,dz)||1;for(const side of [-1,1]){pos.push(x+xx-dz/len*width/2*side,.028,z+dx/len*width/2*side);uv.push(side===-1?0:1,-z/9)}}const indices=[];for(let i=0;i<points.length-1;i++){const n=i*2;indices.push(n,n+2,n+1,n+1,n+2,n+3)}const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(pos,3));geo.setAttribute('uv',new T.Float32BufferAttribute(uv,2));geo.setIndex(indices);geo.computeVertexNormals();const mat=path.clone();mat.side=T.DoubleSide;g.add(new T.Mesh(geo,mat))}
 function hill(xx,z,rx,rz,height){if(!safe(xx,z,Math.min(rx,rz)*.8))return;const geo=new T.SphereGeometry(1,20,10,0,Math.PI*2,0,Math.PI/2);const a=geo.attributes.position;for(let i=0;i<a.count;i++){const vx=a.getX(i),vy=a.getY(i),vz=a.getZ(i);a.setXYZ(i,vx*rx,hillSurface(vx*rx,vz*rz,rx,rz,height),vz*rz)}geo.computeVertexNormals();add(geo,soil,xx,0,z);registerHill(x+xx,z,rx,rz,height)}
 function grove(cx,cz,count,radius){const trunks=new T.InstancedMesh(new T.CylinderGeometry(.22,.5,1,6),wood,count),crowns=new T.InstancedMesh(new T.IcosahedronGeometry(1,1),leaves,count*2),o=new T.Object3D();let n=0;for(let i=0;i<count;i++){const a=i*2.399,rr=Math.sqrt((i+.5)/count)*radius,xx=cx+Math.cos(a)*rr,z=cz+Math.sin(a)*rr;if(!safe(xx,z,1.5)||Math.abs(xx)<18)continue;const height=6+(i*7%5)+Math.sin(i)*1.2;o.position.set(x+xx,height/2,z);o.scale.set(1,height,1);o.rotation.set(0,i,Math.sin(i)*.06);o.updateMatrix();trunks.setMatrixAt(n,o.matrix);for(let j=0;j<2;j++){o.position.y=height*(.72+j*.17);o.scale.set(2.7-j*.5,2.8-j*.4,2.5);o.updateMatrix();crowns.setMatrixAt(n*2+j,o.matrix)}wall(x+xx,z,0,0,height,.48);n++}trunks.count=n;crowns.count=n*2;g.add(trunks,crowns)}
 function hut(xx,z){root.userData.decorBuildings??=[];root.userData.decorBuildings.push([x+xx-4,z-3.5,8,7]);box(xx,2,z,8,4,7);box(xx,4.1,z,9,.25,8,metal);box(xx,1.15,z+3.55,1.5,2.3,.12,metal);const window=new T.MeshBasicMaterial({color:0xe7bc7b});box(xx-2.5,2.1,z+3.56,.8,1,.1,window);wall(x+xx,z,8,7,4);for(let i=0;i<7;i++){const log=add(new T.CylinderGeometry(.27,.27,3,7),wood,xx+7+(i%3)*.65,.3+Math.floor(i/3)*.5,z-1);log.rotation.x=Math.PI/2}}
 function wreck(xx,z){box(xx,.7,z,3,.3,4);for(const s of [-1,1]){const wheel=add(new T.TorusGeometry(.7,.11,6,12),wood,xx+s*1.6,.6,z-1);wheel.rotation.y=Math.PI/2}for(let i=0;i<4;i++){const plank=box(xx+2+i*.4,.15,z+i*.7,.18,.14,3);plank.rotation.y=.4+i*.6}}
 if(zone==='highroad'){
  trail([[0,-22],[5,-62],[9,-101],[-2,-154],[-9,-205],[-4,-252],[0,-288]],8);trail([[7,-92],[24,-98],[43,-110],[54,-138]],4);
  hill(-104,-80,18,27,9);hill(-38,-102,13,21,5.5);hill(105,-147,19,28,12);hill(39,-229,16,21,8);hill(-87,-252,25,20,6);grove(-68,-139,38,29);grove(69,-62,28,24);grove(-66,-237,22,20);hut(43,-109);wreck(58,-140);
  for(const [xx,z,rx,rz] of [[-36,-78,25,36],[44,-167,30,49],[-43,-248,27,24]]){const patch=add(new T.CircleGeometry(1,24),soil,xx,.012,z);patch.rotation.x=-Math.PI/2;patch.scale.set(rx,rz,1)}
  const scrub=new T.InstancedMesh(new T.SphereGeometry(.38,9,6),leaves,120),o=new T.Object3D();let shrubs=0;for(let i=0;i<120;i++){const xx=Math.sin(i*2.399)*(22+i%8*11),z=-37-i*17%245;if(!safe(xx,z,1))continue;o.position.set(x+xx,.17,z);o.rotation.set(.1*Math.sin(i),i,.08*Math.cos(i));o.scale.set(1+i%3*.3,.5+i%2*.2,1);o.updateMatrix();scrub.setMatrixAt(shrubs++,o.matrix)}scrub.count=shrubs;g.add(scrub);
  // The sawmill's broken wheel is a silhouette visible from the road.
  const wheel=add(new T.TorusGeometry(3.2,.35,7,18),wood,57,3.5,-106);wheel.rotation.y=Math.PI/2;for(let i=0;i<8;i++){const spoke=box(57,3.5,-106,.2,.2,6.2);spoke.rotation.x=i*Math.PI/4}box(57,.8,-106,2,1.6,4,rock);
 }else if(zone==='pass'){hill(-78,-87,20,26,10);hill(76,-186,18,30,13);grove(-57,-222,18,16);wreck(-34,-57);trail([[-7,-63],[-34,-58],[-49,-70]],3)}
 else if(zone==='road'){hill(-75,-83,19,30,6);hill(75,-185,24,19,8);grove(-64,-125,25,19);hut(65,-67);wreck(-44,-181)}
 else if(zone==='quarry'){for(const [xx,z,len] of [[-57,-91,24],[66,-164,32]]){for(let i=0;i<6;i++)box(xx,.2,z-i*3,len,.4,1.5,rock);box(xx,3,z-8,.3,6,.3,wood);box(xx+7,6,z-8,14,.3,.3,wood);const hook=add(new T.TorusGeometry(.7,.13,6,16,Math.PI*1.4),metal,xx+12,2.8,z-8);box(xx+12,4.7,z-8,.08,3,.08,metal)}}
 else if(zone==='marsh'){for(const [xx,z] of [[-28,-110],[62,-173],[-57,-240]]){const ribs=add(new T.TorusGeometry(5,.22,7,22,Math.PI),wood,xx,.12,z);ribs.rotation.x=Math.PI/2;for(let i=0;i<8;i++)box(xx+(i-4)*.65,.08,z, .17,.15,7).rotation.y=.13}for(let i=0;i<70;i++){const xx=Math.sin(i*2.4)*(48+i%6*10),z=-58-(i*17%240);const reed=add(new T.ConeGeometry(.15,2.5+i%3*.3,4),leaves,xx,.5,z);reed.rotation.z=Math.sin(i)*.13}}
 else if(zone==='abbey'){for(const [xx,z] of [[-88,-77],[79,-148],[-78,-224]]){box(xx,1.2,z,10,2.4,1,rock);for(let i=0;i<4;i++){const slab=box(xx-4+i*2,.2,z+4+i%2,1.5,.4,3,rock);slab.rotation.y=i*.8}}for(const [xx,z] of [[-95,-120],[90,-237]]){const arch=add(new T.TorusGeometry(5,.7,8,18,Math.PI),rock,xx,0,z);wall(x+xx,z,10,1,5)}grove(-93,-179,12,12)}
 else if(zone==='aerie'){hill(-80,-95,22,34,14);hill(72,-70,19,25,9);for(let i=0;i<9;i++){const rib=add(new T.TorusGeometry(4+i%3,.32,7,16,Math.PI),rock,-61+i*2.2,.1,-166+i*2);rib.rotation.y=.7}for(let i=0;i<14;i++){const basalt=add(new T.CylinderGeometry(.7,1.1,4+i%4,6),metal,48+Math.sin(i*2)*14,2+i%4/2,-53-i*8);basalt.rotation.z=Math.sin(i)*.18}}
 else if(zone==='underworks'){for(const [xx,z] of [[-71,-116],[64,-221],[-62,-274]]){box(xx,2,z,9,4,7,rock);wall(x+xx,z,9,7,4);box(xx,4.1,z,9.5,.4,7.5,metal);box(xx,2,z+3.55,4,1.7,.12,new T.MeshBasicMaterial({color:0x91452b}));for(let i=0;i<3;i++)box(xx-3+i*3,1,z+6,1.5,2,1.5,metal)}for(const [xx,z] of [[-103,-65],[91,-151],[-99,-249]]){add(new T.CylinderGeometry(.5,.5,7,10),metal,xx,3.5,z);const bend=add(new T.TorusGeometry(1,.5,7,12,Math.PI/2),metal,xx+1,6,z);box(xx+4,7,z,6,1,1,metal)}for(const side of [-1,1])for(let i=0;i<14;i++)box(side*7,.035,-92-i*13,.12,.06,10,metal)}
 else if(zone==='stonehaven'){// Towns retain level paving: workshop goods and distinct garden/forge yards.
  for(const [xx,z] of [[-45,-83],[66,-169],[-67,-210]]){for(let i=0;i<4;i++)box(xx+i*1.1,.5,z+i%2,1,1,1,wood);const spool=add(new T.CylinderGeometry(.65,.65,1.2,10),wood,xx-2,.6,z);box(xx-2,1.25,z,1.5,.1,1.5,metal)}
 }else if(zone==='fortress'||zone==='siege'){for(const [xx,z] of [[-63,-77],[58,-118]]){wreck(xx,z);for(let i=0;i<6;i++)box(xx-4+i*1.4,.3,z-7,1.3,.6,1.1,wood)}}
 else if(zone==='manor'){grove(-89,-54,18,17);for(let i=0;i<8;i++){const grave=box(83,1,-45-i*12,1.8,2,.3,rock);grave.rotation.z=Math.sin(i)*.08}}
 return g;
}
